h.append(P.tab("pr_verdict", "아이디어별 판정과 도출점", ["아이디어", "검정과 근거", "판정", "도출점"], verdict, widths=["22%", "34%", "17%", "27%"]))
h.append(P.h3("4.2 한계와 남은 목표"))
h.append(P.p("이 보고서의 판정에는 다음 한계가 있다. 첫째, 월 간 분석은 월 수가 100개 안팎이고 월 값이 서로 이어져 있어 구간을 넓게 읽어야 한다. 둘째, 만기 확정 표본은 발급 시기가 2017년 3월 이전으로 제한되어 시간 외 국면을 다루지 못한다. 셋째, 시험 자료가 원자료의 무작위 표본이라 학습·시험 점수에는 같은 시기가 섞여 있고, 모형과 규칙 일부는 시험 점수를 본 뒤 고른 것이어서 시험 결과는 사후 선택의 영향을 받는다. 넷째, 점수에 들어간 발급연도와 금리 열은 무작위 분할에서 시대 효과를 학습하므로 시간 외로 갈 때 같은 효과를 기대할 수 없다. 다섯째, 3.3절의 외부 변수 설명은 인과가 아니라 예측 연관이다."))
h.append(P.p("남은 목표는 세 가지이다. 첫째, 만기가 지나지 않은 대출을 중도절단으로 반영하는 학습(경쟁위험 가중)을 도입해 3.2절의 월 간 배분 몫이 사라지는지 확인한다. 둘째, 시대 열을 제외한 점수를 같은 규칙으로 시간 외(2017–20년 발급)에 적용해 월 안 선별만으로 성과가 유지되는지 본다. 셋째, 3.4절에서 승인 규모 조절의 이득이 없었으므로, 위험회피 수준 λ를 월 상태로 조절하는 설계를 별도 검정으로 세운다."))
h.append(P.h3("4.3 결론"))
